grid=[[1,2,5],[7,3,6],[7,6,5]]
def transform(grid):
    rows=[]
    for i,row in enumerate(grid):
        expanded=[]
        for j,v in enumerate(row): expanded.extend([v] if j==len(row)//2 else [v,v])
        rows.extend([expanded] if i==len(grid)//2 else [expanded,expanded])
    return rows
out=transform(grid)
print(out)
